const ProductDetailScreen: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { addToCart } = useCart();
  const product = PRODUCTS.find(p => p.id === id) || PRODUCTS[0];

  const [quantity, setQuantity] = useState(1);
  const [extras, setExtras] = useState<string[]>([]);

  const handleExtraToggle = (name: string) => {
    setExtras(prev => prev.includes(name) ? prev.filter(e => e !== name) : [...prev, name]);
  };

  const getExtraPrice = (name: string) => {
    switch(name) {
        case 'Queso Extra': return 3000;
        case 'Tocineta Crujiente': return 4500;
        case 'Huevo de Codorniz': return 2000;
        default: return 0;
    }
  };

  const currentTotal = (product.price + extras.reduce((sum, e) => sum + getExtraPrice(e), 0)) * quantity;

  const handleAddToCart = () => {
    addToCart(product, quantity, extras);
    navigate('/cart');
  };

