        </div>
      </div>

      {/* Footer */}
      <div className="fixed bottom-0 left-0 right-0 z-50 rounded-t-2xl bg-white px-6 pb-8 pt-4 shadow-[0_-8px_30px_rgba(0,0,0,0.12)] max-w-md mx-auto">
        <div className="flex items-center gap-4">
