            onClick={handleAddToCart}
            className="flex h-14 w-full flex-1 items-center justify-between rounded-full bg-primary px-6 text-[#181611] shadow-lg shadow-primary/25 transition active:scale-[0.98]"
          >
            <span className="text-base font-bold">Agregar</span>
            <span className="text-base font-bold">${currentTotal.toLocaleString()}</span>
          </button>
        </div>
      </div>
    </div>
  );
};

