              <div className="w-full max-w-xs">
                  <input 
                    type="password" 
                    value={pin}
                    onChange={(e) => setPin(e.target.value)}
                    placeholder="Ingrese PIN (2024)"
                    className="w-full bg-white/10 border border-white/20 rounded-xl p-4 text-center text-xl tracking-widest mb-4 focus:ring-primary focus:border-primary"
                    maxLength={4}
                  />
                  <button 
                    onClick={() => handleLogin(pin)}
                    className="w-full bg-primary text-background-dark font-bold py-4 rounded-xl hover:bg-yellow-400 transition-colors"
                  >
                      Desbloquear
                  </button>
                  <button onClick={() => navigate('/')} className="w-full mt-4 text-gray-400 text-sm hover:text-white">
                      Volver a Inicio
                  </button>
              </div>
          </div>
      );
  }

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden shadow-2xl bg-white">
      {/* Header */}
      <header className="flex items-center p-4 pt-6 pb-2 justify-between sticky top-0 z-20 bg-white/90 backdrop-blur-md">
        <div className="flex items-center gap-3">
          <div onClick={() => navigate('/')} className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary/20 text-primary cursor-pointer">
            <span className="material-symbols-outlined text-2xl">local_pizza</span>
          </div>
          <div>
            <h2 className="text-[#181611] text-lg font-bold leading-tight tracking-[-0.015em]">POTATOES</h2>
            <p className="text-xs font-medium text-gray-500 flex items-center gap-1">
              <span className="material-symbols-outlined text-[14px]">admin_panel_settings</span> Dashboard
            </p>
          </div>
        </div>
        <div className="flex items-center justify-end">
          <button onClick={() => setIsAuthenticated(false)} className="flex items-center justify-center rounded-full h-10 w-10 bg-transparent text-[#181611] hover:bg-gray-100 transition-colors">
            <span className="material-symbols-outlined">logout</span>
          </button>
        </div>
      </header>

      {/* Time Filters */}
      <div className="flex gap-2 p-4 overflow-x-auto no-scrollbar">
        <button className="flex h-9 shrink-0 items-center justify-center gap-x-2 rounded-full bg-[#181611] px-5 shadow-sm transition-transform active:scale-95">
          <p className="text-white text-sm font-bold leading-normal">General</p>
        </button>
      </div>

      {/* KPI Stats */}
      <div className="flex flex-col gap-4 p-4">
        {/* Main Hero Card */}
        <div className="relative overflow-hidden rounded-xl bg-primary p-6 shadow-lg text-[#181611]">
          <div className="absolute -right-6 -top-6 h-32 w-32 rounded-full bg-white/20 blur-2xl"></div>
